type CoreSalesServiceServer interface {
	// ListOrderDiscounts returns a paginated list of order discounts.
	ListOrderDiscounts(context.Context, *ListOrderDiscountsRequest) (*ListOrderDiscountsResponse, error)
	// GetOrderDiscount returns a single order discount by its ID.
	GetOrderDiscount(context.Context, *GetOrderDiscountRequest) (*GetOrderDiscountResponse, error)
	// CreateOrderDiscount creates a new order discount.
	CreateOrderDiscount(context.Context, *CreateOrderDiscountRequest) (*CreateOrderDiscountResponse, error)
	// UpdateOrderDiscount updates an existing order discount.
	UpdateOrderDiscount(context.Context, *UpdateOrderDiscountRequest) (*UpdateOrderDiscountResponse, error)
	// DeleteOrderDiscount deletes an order discount by its ID.
	DeleteOrderDiscount(context.Context, *DeleteOrderDiscountRequest) (*DeleteOrderDiscountResponse, error)
	// FindOrderDiscountByCode looks up an order discount by its unique code.
	FindOrderDiscountByCode(context.Context, *FindOrderDiscountByCodeRequest) (*FindOrderDiscountByCodeResponse, error)
	// Returns order discounts by ID for the api-gateway include resolver.
	BatchGetOrderDiscountsByIDs(context.Context, *BatchGetOrderDiscountsByIDsRequest) (*BatchGetOrderDiscountsByIDsResponse, error)
	// ListSalesOrderStatuses returns a paginated list of sales order statuses.
	ListSalesOrderStatuses(context.Context, *ListSalesOrderStatusesRequest) (*ListSalesOrderStatusesResponse, error)
	// Returns sales order statuses by ID for the api-gateway include resolver.
	BatchGetSalesOrderStatusesByIDs(context.Context, *BatchGetSalesOrderStatusesByIDsRequest) (*BatchGetSalesOrderStatusesByIDsResponse, error)
	// ListSalesOrders returns a paginated list of sales orders.
	ListSalesOrders(context.Context, *ListSalesOrdersRequest) (*ListSalesOrdersResponse, error)
	// GetSalesOrder returns a single sales order by ID.
	GetSalesOrder(context.Context, *GetSalesOrderRequest) (*GetSalesOrderResponse, error)
	// Returns sales orders by ID for the api-gateway include resolver.
	BatchGetSalesOrdersByIDs(context.Context, *BatchGetSalesOrdersByIDsRequest) (*BatchGetSalesOrdersByIDsResponse, error)
	// CreateSalesOrder creates a new sales order.
	CreateSalesOrder(context.Context, *CreateSalesOrderRequest) (*CreateSalesOrderResponse, error)
	// UpdateSalesOrder updates an existing sales order.
	UpdateSalesOrder(context.Context, *UpdateSalesOrderRequest) (*UpdateSalesOrderResponse, error)
	// DeleteSalesOrder deletes a sales order by ID.
	DeleteSalesOrder(context.Context, *DeleteSalesOrderRequest) (*emptypb.Empty, error)
	// BulkDeleteSalesOrders deletes multiple sales orders.
	BulkDeleteSalesOrders(context.Context, *BulkDeleteSalesOrdersRequest) (*emptypb.Empty, error)
	// ChangeSalesOrderStatus changes the status of a sales order.
	ChangeSalesOrderStatus(context.Context, *ChangeSalesOrderStatusRequest) (*ChangeSalesOrderStatusResponse, error)
	// CheckoutSalesOrder initiates a checkout for a sales order.
	CheckoutSalesOrder(context.Context, *CheckoutSalesOrderRequest) (*CheckoutSalesOrderResponse, error)
	// QuoteSalesOrderLinePrices computes the unit price for each line without creating
	// an order, used to display prices to users (incl. the customer portal).
	QuoteSalesOrderLinePrices(context.Context, *QuoteSalesOrderLinePricesRequest) (*QuoteSalesOrderLinePricesResponse, error)
	// QuoteSalesOrderFreight re-estimates the freight (shipping) charge for an existing
	// order from its current ship-to, carrier, service level, and lines, without mutating it.
	QuoteSalesOrderFreight(context.Context, *QuoteSalesOrderFreightRequest) (*QuoteSalesOrderFreightResponse, error)
	// QuoteSalesOrderCommitment previews the ship-by date a set of commitment inputs would
	// produce, without creating or mutating anything. Serves the order-entry form, which has
	// no order to ask about yet.
	QuoteSalesOrderCommitment(context.Context, *QuoteSalesOrderCommitmentRequest) (*QuoteSalesOrderCommitmentResponse, error)
	// CreateSalesOrderProductionRun creates a production run from a sales order.
	CreateSalesOrderProductionRun(context.Context, *CreateSalesOrderProductionRunRequest) (*CreateSalesOrderProductionRunResponse, error)
	// CreateSalesOrderLine creates a new line on a sales order.
	CreateSalesOrderLine(context.Context, *CreateSalesOrderLineRequest) (*CreateSalesOrderLineResponse, error)
	// ListVolumeDiscounts returns a paginated list of volume discounts.
	ListVolumeDiscounts(context.Context, *ListVolumeDiscountsRequest) (*ListVolumeDiscountsResponse, error)
	// GetVolumeDiscount returns a single volume discount by ID.
	GetVolumeDiscount(context.Context, *GetVolumeDiscountRequest) (*GetVolumeDiscountResponse, error)
	// CreateVolumeDiscount creates a new volume discount.
	CreateVolumeDiscount(context.Context, *CreateVolumeDiscountRequest) (*CreateVolumeDiscountResponse, error)
	// UpdateVolumeDiscount updates an existing volume discount.
	UpdateVolumeDiscount(context.Context, *UpdateVolumeDiscountRequest) (*UpdateVolumeDiscountResponse, error)
	// DeleteVolumeDiscount deletes a volume discount by its ID.
	DeleteVolumeDiscount(context.Context, *DeleteVolumeDiscountRequest) (*emptypb.Empty, error)
	// UpdateSalesOrderLine updates an existing sales order line.
	UpdateSalesOrderLine(context.Context, *UpdateSalesOrderLineRequest) (*UpdateSalesOrderLineResponse, error)
	// DeleteSalesOrderLine deletes a sales order line.
	DeleteSalesOrderLine(context.Context, *DeleteSalesOrderLineRequest) (*emptypb.Empty, error)
	// ReorderSalesOrderLines re-sequences a sales order's product lines to match the
	// given order, keeping credit/freight lines at the bottom of the list.
	ReorderSalesOrderLines(context.Context, *ReorderSalesOrderLinesRequest) (*ReorderSalesOrderLinesResponse, error)
	// CreateCustomerCheckoutSession creates a checkout session for a customer order.
	CreateCustomerCheckoutSession(context.Context, *CreateCustomerCheckoutSessionRequest) (*CreateCustomerCheckoutSessionResponse, error)
	// RecordOrderPayment links a succeeded Stripe payment intent to a sales order.
	// Called by the billing-service when a checkout session completes. Idempotent.
	RecordOrderPayment(context.Context, *RecordOrderPaymentRequest) (*emptypb.Empty, error)
	// ProcessAccountStripeWebhook verifies a Stripe webhook event signed with an
	// account's own webhook secret and links succeeded payment intents to their
	// sales orders. Idempotent.
	ProcessAccountStripeWebhook(context.Context, *ProcessAccountStripeWebhookRequest) (*emptypb.Empty, error)
	mustEmbedUnimplementedCoreSalesServiceServer()
}

